  "name": "write_file",
  "arguments": {
    "path": "index.html",
    "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Reading List</title>
  <style>
    body { font-family: Arial, sans-serif; margin: 20px; }
    .book { border: 1px solid #ccc; padding: 10px; margin: 10px 0; }
    .book h3 { margin: 0 0 5px 0; }
    .book p { margin: 0 0 5px 0; }
    .book button { margin-right: 5px; }
    .tags { display: flex; flex-wrap: wrap; gap: 5px; }
    .tags label { display: flex; align-items: center; }
    .tags input[type="checkbox"] { margin-right: 5px; }
    .search { margin-bottom: 10px; }
    .export-import { margin-top: 20px; }
  </style>
</head>
<body>
  <h1>Reading List</h1>
  <div class="search">
    <input type="text" id="searchInput" placeholder="Search by title or author">
  </div>
  <div class="export-import">
    <button id="exportBtn">Export JSON</button>
    <input type="file" id="importFile" accept="application/json" style="display:none">
    <button id="importBtn">Import JSON</button>
  </div>
  <div id="books"></div>
  <script>
    const STORAGE_KEY = 'reading_list_books';
    let books = [];

    function loadBooks() {
      const data = localStorage.getItem(STORAGE_KEY);
      if (data) {
        try {
          books = JSON.parse(data);
        } catch (e) {
          books = [];
        }
      }
    }

    function saveBooks() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(books));
    }

    function render() {
      const container = document.getElementById('books');
      container.innerHTML = '';
      books.forEach(book => {
        const div = document.createElement('div');
        div.className = 'book';
        div.id = 'book-' + book.id;
        div.innerHTML = `
          <h3>${escapeHtml(book.title)}</h3>
          <p>Author: ${escapeHtml(book.author)}</p>
          <p>Tags: ${book.tags.map(t => `<span class="tag">${escapeHtml(t)}</span>`).join(' ')}</p>
          <button onclick="deleteBook('${book.id}')">Delete</button>
        `;
        container.appendChild(div);
      });
    }

    function escapeHtml(str) {
      const div = document.createElement('div');
      div.textContent = str;
      return div.innerHTML;
    }

    function addBook() {
      const title = document.getElementById('titleInput').value.trim();
      const author = document.getElementById('authorInput').value.trim();
      const tagsInput = document.getElementById('tagsInput').value.trim();
      const tags = tagsInput.split(',').map(t => t.trim().toLowerCase()).filter(Boolean);
      if (!title || !author || !tags.length) {
        alert('Title, author, and at least one tag are required.');
        return;
      }
      const id = 'book-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);
      books.push({ id, title, author, tags });
      saveBooks();
      render();
      document.getElementById('titleInput').value = '';
      document.getElementById('authorInput').value = '';
      document.getElementById('tagsInput').value = '';
    }

    function deleteBook(id) {
      books = books.filter(b => b.id !== id);
      saveBooks();
      render();
    }

    function searchBooks() {
      const query = document.getElementById('searchInput').value.toLowerCase().trim();
      const filtered = books.filter(b => b.title.toLowerCase().includes(query) || b.author.toLowerCase().includes(query));
      renderBooks(filtered);
    }

    function renderBooks(booksToRender) {
      const container = document.getElementById('books');
      container.innerHTML = '';
      booksToRender.forEach(book => {
        const div = document.createElement('div');
        div.className = 'book';
        div.id = 'book-' + book.id;
        div.innerHTML = `
          <h3>${escapeHtml(book.title)}</h3>
          <p>Author: ${escapeHtml(book.author)}</p>
          <p>Tags: ${book.tags.map(t => `<span class="tag">${escapeHtml(t)}</span>`).join(' ')}</p>
          <button onclick="deleteBook('${book.id}')">Delete</button>
        `;
        container.appendChild(div);
      });
    }

    function exportBooks() {
      const data = JSON.stringify(books, null, 2);
      const blob = new Blob([data], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'reading_list.json';
      a.click();
      URL.revokeObjectURL(url);
    }

    function importBooks() {
      const fileInput = document.getElementById('importFile');
      fileInput.click();
    }

    function handleImport(event) {
      const file = event.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = function(e) {
        try {
          const imported = JSON.parse(e.target.result);
          if (!Array.isArray(imported) || !imported.every(b => b.id && b.title && b.author && Array.isArray(b.tags) && b.tags.every(t => typeof t === 'string'))) {
            alert('Invalid format: must be an array of books with id, title, author, and tags array.');
            return;
          }
          books = imported;
          saveBooks();
          render();
        } catch (err) {
          alert('Invalid JSON: ' + err.message);
        }
      };
      reader.readAsText(file);
      event.target.value = '';
    }

    document.getElementById('addBook').addEventListener('click', addBook);
    document.getElementById('searchInput').addEventListener('input', searchBooks);
    document.getElementById('exportBtn').addEventListener('click', exportBooks);
    document.getElementById('importBtn').addEventListener('click', importBooks);
    document.getElementById('importFile').addEventListener('change', handleImport);

    loadBooks();
    render();
  </script>
</body>\

