{
  "name": "write_file",
  "arguments": {
    "path": "index.html",
    "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Reading List</title>
  <style>
    body { font-family: Arial, sans-serif; max-width: 800px; margin: 2rem auto; padding: 0 1rem; }
    .book { border: 1px solid #ccc; border-radius: 4px; padding: 0.5rem; margin-bottom: 0.5rem; }
    .book button { margin-right: 0.5rem; }
    .tags { display: flex; flex-wrap: wrap; gap: 0.25rem; }
    .tags label { display: inline-block; }
    .tags input[type="checkbox"] { margin-right: 0.25rem; }
    .search { margin-bottom: 1rem; }
    .export-import { margin-top: 1rem; }
  </style>
</head>
<body>
  <h1>Reading List</h1>
  <div class="search">
    <label>Search books: <input type="text" id="searchInput" placeholder="title or author"></label>
  </div>
  <div class="book-list" id="bookList"></div>
  <div class="export-import">
    <button id="exportBtn">Export JSON</button>
    <input type="file" id="importFile" accept="application/json" style="display:none">
    <button id="importBtn">Import books</button>
  </div>
  <script>
    const STORAGE_KEY = 'reading_list';
    let books = [];

    function load() {
      try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (raw) {
          const parsed = JSON.parse(raw);
          if (Array.isArray(parsed) && parsed.every(b => b.id && b.title && b.author && b.tags && Array.isArray(b.tags))) {
            books = parsed;
          }
        }
      } catch (e) { /* ignore */ }
    }

    function save() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(books));
    }

    function render() {
      const list = document.getElementById('bookList');
      list.innerHTML = '';
      if (books.length === 0) {
        list.innerHTML = '<p>No books yet.</p>';
        return;
      }
      books.forEach(b => {
        const div = document.createElement('div');
        div.className = 'book';
        div.id = 'book-' + b.id;
        div.innerHTML = `
          <strong>${escapeHtml(b.title)}</strong> by ${escapeHtml(b.author)}<br>
          <span class="tags">${b.tags.map(t => `<label><input type="checkbox" name="tag-${b.id}" value="${t}" checked> ${escapeHtml(t)}</label>`).join('')}</span>
          <button onclick="deleteBook('${b.id}')">Delete</button>
        `;
        list.appendChild(div);
      });
    }

    function escapeHtml(s) { return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

    function addBook() {
      const title = document.getElementById('bookTitle').value.trim();
      const author = document.getElementById('bookAuthor').value.trim();
      const tagsInput = document.getElementById('bookTags').value.trim();
      const tags = tagsInput.split(',').map(t => t.trim()).filter(t => t);
