<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Reading List</title>
  <style>
    body { font-family: Arial, sans-serif; margin: 20px; }
    .book { border: 1px solid #ccc; padding: 10px; margin: 10px 0; }
    .book h3 { margin: 0 0 5px; }
    .book p { margin: 0 0 5px; }
    .book .tags { margin: 0; }
    .book .tags label { display: inline-block; margin-right: 5px; }
    .book .tags input[type="checkbox"] { margin-right: 5px; }
    .book .delete { float: right; }
    .book .delete button { background: #f44336; color: white; border: none; padding: 5px 10px; cursor: pointer; }
    .book .delete button:hover { background: #d32f2f; }
    .search-box { margin-bottom: 10px; }
    .search-box input { width: 100%; padding: 5px; }
    .export-box { margin-bottom: 10px; }
    .export-box button { background: #4caf50; color: white; border: none; padding: 5px 10px; cursor: pointer; }
    .export-box button:hover { background: #388e3c; }
    .import-box { margin-bottom: 10px; }
    .import-box input[type="file"] { margin-right: 5px; }
    .import-box button { background: #2196f3; color: white; border: none; padding: 5px 10px; cursor: pointer; }
    .import-box button:hover { background: #1976d2; }
    .alert { margin-top: 10px; padding: 10px; border: 1px solid #ccc; }
    .alert.error { background: #ffebee; color: #c62828; }
    .alert.success { background: #e8f5e9; color: #2e7d32; }
  </style>
</head>
<body>
  <h1>Reading List</h1>
  <div class="search-box">
    <input type="text" id="search-input" placeholder="Search books...">
  </div>
  <div class="export-box">
    <button id="export-btn">Export JSON</button>
  </div>
  <div class="import-box">
    <input type="file" id="import-file" accept=".json">
    <button id="import-btn">Import books</button>
  </div>
  <div id="books-container"></div>
  <div id="alert" class="alert" role="alert"></div>

  <script>
    const STORAGE_KEY = 'reading_list';
    let books = [];

    function loadBooks() {
      const data = localStorage.getItem(STORAGE_KEY);
      if (data) {
        try {
          books = JSON.parse(data);
        } catch (e) {
          books = [];
        }
      }
    }

    function saveBooks() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(books));
    }

    function renderBooks() {
      const container = document.getElementById('books-container');
      const search = document.getElementById('search-input').value.toLowerCase();
      const filtered = books.filter(book =>
        book.title.toLowerCase().includes(search) ||
        book.author.toLowerCase().includes(search)
      );
      container.innerHTML = '';
      filtered.forEach(book => {
        const div = document.createElement('div');
        div.className = 'book';
        div.id = `book-${book.id}`;
        div.innerHTML = `
          <h3>${book.title}</h3>
          <p>Author: ${book.author}</p>
          <div class="tags">
            ${book.tags.map(tag => `
              <label>
                <input type="checkbox" name="tag" value="${tag}" checked>
                ${tag}
              </label>
            `).join('')}
          </div>
          <div class="delete">
            <button class="delete-btn" data-id="${book.id}">Delete</button>
          </div>
        `;
        container.appendChild(div);
      });
      attachDeleteListeners();
    }

    function attachDeleteListeners() {
      document.querySelectorAll('.delete-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          const id = btn.dataset.id;
          books = books.filter(b => b.id !== id);
          saveBooks();
          renderBooks();
        });
      });
    }

    function addBook() {
      const title = document.getElementById('book-title').value.trim();
      const author = document.getElementById('book-author').value.trim();
      const tagsInput = document.getElementById('book-tags').value;
      const tags = tagsInput
        .split(',')
        .map(t => t.trim().toLowerCase())
        .filter(t => t.length > 0)
        .map(t => t.charAt(0).toUpperCase() + t.slice(1));
      if (!title || !author || !tags.length) {
        showAlert('All fields are required.', 'error');
        return;
      }
      const id = 'book-' + Date.now();
      books.push({ id, title, author, tags });
      saveBooks();
      renderBooks();
      clearForm();
      showAlert('Book added successfully.', 'success');
    }

    function clearForm() {
      document.getElementById('book-title').value = '';
      document.getElementById('book-author').value = '';
      document.getElementById('book-tags').value = '';
    }

    function showAlert(message, type) {
      const alert = document.getElementById('alert');
      alert.className = 'alert ' + type;
      alert.innerHTML = message;
      alert.style.display = 'block';
      setTimeout(() => alert.style.display = 'none', 3000);
    }

    function exportBooks() {
      const data = JSON.stringify(books, null, 2);
      const blob = new Blob([data], { type: 'application/json' });
